"use client"
import React from 'react'
import { useState } from 'react';
// import toast from 'react-hot-toast';
import { useRouter } from 'next/navigation';
import { useUserStore } from "../../../store/userStore";

const API_URL = 'http://localhost:4444'; // Define API URL

interface TwoFAProps {
    userId: number | null;
    onLoginSuccess: () => void;
}


// Replace the placeholder _2fa function with the final component
const _2fa = ({ userId, onLoginSuccess }: TwoFAProps) => {
    const [inputValues, setInputValues] = useState<string[]>(['', '', '', '', '', '']);
    const [isLoading, setIsLoading] = useState(false);
    const router = useRouter();
    const setUser = useUserStore((state) => state.setUser);
    
    
    if (!userId) {
        // Fallback if ID is somehow missing
        // toast.error("User session timed out. Please sign in again.");
        // router.push('/signIn');
        return null;
    }

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        const fullCode = inputValues.join('');

        if (fullCode.length !== 6) {
            // toast.error("Please enter the full 6-digit code.");
            return;
        }

        setIsLoading(true);

        try {
            const response = await fetch(`${API_URL}/verifyTOTPAndLogin`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ 
                    id_user: userId, 
                    verificationCode: fullCode 
                }),
            });

            const data = await response.json();

            if (!response.ok || !data.success) {
                // toast.error(data.message || 'Invalid 2FA code. Please try again.');
                return;
            }
            
            // Final success: store token and user data
            if (data.token) {
                localStorage.setItem('jwt_token', data.token);
            }
            if (data.user) {
                setUser(data.user);
            }
            
            // toast.success('Verification successful! Logging in...');
            onLoginSuccess(); // Hide 2FA component
            
            setTimeout(() => {
                router.push('/');
            }, 1000);

        } catch (error) {
            console.error("Network error during 2FA verification:", error);
            // toast.error('Network error. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };
    
    // Improved input handling
    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>, index: number) => {
        const { value } = e.target;
        
        if (!/^[0-9]$/.test(value) && value !== '') {
            return; // Only allow single digit numbers
        }

        const newInputs = [...inputValues];
        newInputs[index] = value;
        setInputValues(newInputs);

        if (value && index < 5) {
            const nextInput = e.target.parentElement?.querySelector(`input:nth-child(${index + 2})`) as HTMLInputElement;
            if (nextInput) {
                nextInput.focus();
            }
        } else if (!value && index > 0) {
            const prevInput = e.target.parentElement?.querySelector(`input:nth-child(${index})`) as HTMLInputElement;
            if (prevInput) {
                prevInput.focus();
            }
        }
    };
    
    const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
        const pastedData = e.clipboardData.getData('text');
        if (pastedData.match(/^\d{6}$/)) {
            e.preventDefault();
            const newInputs = pastedData.split('');
            setInputValues(newInputs);
            // Optionally focus on the last input
            const lastInput = e.currentTarget.parentElement?.querySelector('input:last-child') as HTMLInputElement;
            if (lastInput) {
                 lastInput.focus();
            }
        }
    };


    return (
        <div className='min-h-screen w-full flex items-center justify-center bg-black p-3 sm:p-4 md:p-6 lg:p-8'> 
           <div className="flex flex-col items-center justify-center h-full bg-black
           p-8 border-2 border-gray-400 rounded-2xl shadow-2xl max-w-md mx-auto max-h-100 text-white">
            <h1 className="mb-4 text-2xl font-bold">Two-Factor Authentication</h1>
            <p className="mb-8 text-center text-gray-500 text-base">
                Please enter the 6-digit code from your authenticator app to continue.
            </p>
            <form className="w-full max-w-sm mb-4 flex flex-col items-around gap-4"
                onSubmit={handleSubmit}
            >
                {/* 6 input each one contain 1 digit */}
                <div className="mb-4 flex justify-between gap-2">
                    {inputValues.map((value, i) => (
                        <input
                            key={i}
                            type="text"
                            maxLength={1}
                            autoFocus={i === 0}
                            value={value}
                            disabled={isLoading}
                            className="w-10 sm:w-12 rounded-xl border border-gray-600 p-2 text-center text-xl bg-gray-900 text-white focus:border-blue-400 focus:outline-none"
                            onChange={(e) => handleInputChange(e, i)}
                            onPaste={i === 0 ? handlePaste : undefined}
                            onKeyDown={(e) => {
                                if (e.key === 'Backspace' && !inputValues[i] && i > 0) {
                                    const prevInput = e.currentTarget.parentElement?.querySelector(`input:nth-child(${i})`) as HTMLInputElement;
                                    if (prevInput) {
                                        prevInput.focus();
                                    }
                                }
                            }}
                        />
                    ))}
                </div>
                <div className='mt-6 sm:mt-8 flex flex-col sm:flex-row justify-end gap-3'>
                    <button
                        type="submit"
                        disabled={isLoading || inputValues.join('').length !== 6}
                        className="w-full rounded-xl bg-blue-600 px-4 py-3 font-bold text-white hover:bg-blue-700 hover:cursor-pointer active:scale-95 disabled:opacity-50"
                        >
                        {isLoading ? 'Verifying...' : 'Verify & Log In'}
                    </button>
                </div>
            </form>

        </div>
        </div>
    )
}
export default _2fa;